/* Independent mechanical assertions over generated bytes, not a scholar review.
 * Does not import the compiler or authoring draft modules.
 */
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import vm from 'node:vm';import {fileURLToPath} from 'node:url';
const root=path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const flag=process.argv.indexOf('--out');assert.ok(flag>=0&&process.argv[flag+1]);const out=path.resolve(process.argv[flag+1]),site=path.join(out,'site');
const raw=p=>fs.readFileSync(path.join(root,p));const json=p=>JSON.parse(raw(p));const candidate=p=>fs.readFileSync(path.join(site,p));const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const prior=json('nitnem/learning/course.v14.json'),course=JSON.parse(candidate('learning/course.v15.json')),report=JSON.parse(fs.readFileSync(path.join(out,'evidence/build.json'))),manifest=json('nitnem/data/library.json');
const packs=Object.fromEntries(Object.entries(manifest.entries).map(([n,e])=>[n,json('nitnem/'+e.path)]));
const units=packs.jaap.units.filter(u=>Number(u.id.slice(4))>=91&&Number(u.id.slice(4))<=105);
const expectedLines=units.flatMap(u=>u.lines.map(l=>'jaap|'+l.id)),expectedUnits=units.map(u=>'jaap|'+u.id);
const newLines=Object.keys(course.closeTextNotes).filter(k=>!Object.hasOwn(prior.closeTextNotes,k)),newUnits=Object.keys(course.unitLessons).filter(k=>!Object.hasOwn(prior.unitLessons,k));
const sameKeys=(a,b)=>assert.deepEqual([...a].sort(),[...b].sort());const results=[];
function check(name,fn){try{fn();results.push({name,status:'PASS'});}catch(e){results.push({name,status:'FAIL',error:e.message});}}
check('Pinned V14 course and all fourteen packaged prior courses remain byte-identical',()=>{
 assert.equal(sha(raw('nitnem/learning/course.v14.json')),'3a0d15041cccb837b063165ff5acbcdb3345a59616b57fca392c8be0d9f801d9');
 for(let i=1;i<=14;i++)assert.ok(candidate('learning/course.v'+i+'.json').equals(raw('nitnem/learning/course.v'+i+'.json')));
});
check('Pinned manifest and all source packs retain every source hash and unapproved status',()=>{
 assert.equal(sha(raw('nitnem/data/library.json')),'b5865b293acc3ea91a20487dd82efd6f503d22dc5823bc2a67effcd146840d7a');
 let records=0,count=0;
 for(const [b,e] of Object.entries(manifest.entries)){
  assert.ok(candidate(e.path).equals(raw('nitnem/'+e.path)));assert.equal(sha(candidate(e.path)),e.sha256);
  const p=packs[b];assert.equal(p.humanCollationApproved,false);assert.equal(p.rightsCleared,false);assert.equal(p.sourceRepositoryCommit,manifest.sourceCommit);
  count+=p.units.length;for(const u of p.units)for(const l of u.lines){records++;assert.equal(sha(l.text),l.sha256);}
 }
 assert.equal(records,1361);assert.equal(count,327);
});
check('All 919 earlier notes and 217 earlier studies remain exact, including editorial/reuse history',()=>{
 assert.equal(Object.keys(prior.closeTextNotes).length,919);assert.equal(Object.keys(prior.unitLessons).length,217);
 for(const [k,v] of Object.entries(prior.closeTextNotes))assert.deepEqual(course.closeTextNotes[k],v,k);
 for(const [k,v] of Object.entries(prior.unitLessons))assert.deepEqual(course.unitLessons[k],v,k);
 assert.deepEqual(course.editorialAmendments,prior.editorialAmendments);assert.deepEqual(course.sourceReuseEvidence,prior.sourceReuseEvidence);
});
check('Exactly sixty new occurrences and fifteen new studies cover 91-105, without counting headings',()=>{
 assert.deepEqual(units.map(u=>u.id),Array.from({length:15},(_,i)=>'jaap'+String(91+i).padStart(3,'0')));
 assert.ok(units.every(u=>u.lines.length===4));assert.equal(expectedLines.length,60);sameKeys(newLines,expectedLines);sameKeys(newUnits,expectedUnits);
 assert.deepEqual(units.filter(u=>u.metricalHeadings.length).map(u=>u.id),['jaap094','jaap096','jaap099','jaap103']);
 assert.deepEqual(units.flatMap(u=>u.metricalHeadings.map(h=>h.sha256)),['616c6f2800d26cf288225e08ce824f4d77868f538342ddc878fa2a2995032e4d','a139714edb3e28ffba635f33da8cf14c9d43eadc729480656e119fa18de1014c','f8a43194c47ada1dbb9ff3a36a003f0704082a6113c1c7c689fc5d35ba08d6c1','bf7c354614d9be58c444a6de38e46cf2a74596804479157165be2df3240fa082']);
});
check('Every added note is bilingual, source-bound, non-generic and explicitly unreviewed',()=>{
 for(const u of units)for(const l of u.lines){const n=course.closeTextNotes['jaap|'+l.id];assert.equal(n.lineId,l.id);assert.equal(n.sourceSha256,l.sha256);assert.equal(l.held,false);assert.equal(n.status,'DRAFT_AI_UNREVIEWED');assert.equal(n.kind,'SELECTIVE_EDUCATIONAL_PARAPHRASE_NOT_LITERAL_TRANSLATION');assert.ok(n.simpleEn.length>12);assert.match(n.simplePa,/\p{Script=Gurmukhi}/u);assert.ok(n.interpretiveCaution.length>30);assert.ok(!/[\uFFFD\uE000-\uF8FF]/u.test(JSON.stringify(n)));}
});
check('Every added Study has bilingual summary, substantive close reading and exact-source vocabulary',()=>{
 for(const u of units){const l=course.unitLessons['jaap|'+u.id],s=l.study;assert.equal(l.status,'DRAFT_AI_UNREVIEWED');assert.deepEqual(l.sourceAnchor,{id:u.lines[0].id,sha256:u.lines[0].sha256});assert.ok(l.simple.en.length>35);assert.match(l.simple.pa,/\p{Script=Gurmukhi}/u);assert.ok(s.closeReading.split(/\s+/).length>=75);for(const key of ['focus','interpretationCare','reflection','teachBack'])assert.ok(s[key].length>20,key);for(const w of s.words){assert.ok(u.lines.some(x=>x.text.includes(w.gurmukhi)),u.id+' '+w.gurmukhi);assert.equal(w.status,'WORKING_GLOSS_NOT_APPROVED');}assert.ok(!/[\uFFFD\uE000-\uF8FF]/u.test(JSON.stringify(l)));}
});
check('Repeat handling is exact and new-versus-reused coverage accounting is honest',()=>{
 for(const f of ['simpleEn','simplePa']){assert.equal(course.closeTextNotes['jaap|jaap091.line04'][f],prior.closeTextNotes['jaap|jaap087.line01'][f]);assert.equal(course.closeTextNotes['jaap|jaap101.line02'][f],course.closeTextNotes['jaap|jaap099.line02'][f]);}
 assert.equal(course.candidateV15Reuse.length,1);assert.equal(course.candidateV15Reuse[0].from,'jaap|jaap087.line01');assert.equal(course.candidateV15Reuse[0].to,'jaap|jaap091.line04');
 assert.equal(course.coverage.accounting.newJaapLineDrafts,59);assert.equal(course.coverage.accounting.exactSourceReusedLineDrafts,1);assert.equal(course.coverage.accounting.additionalSourceRecords,60);
});
check('Totals reconcile to 979/1361 records and 232/327 studies; other banis retain coverage',()=>{
 assert.equal(course.coverage.closeTextOccurrenceNotes,979);assert.equal(Object.keys(course.closeTextNotes).length,979);assert.equal(course.coverage.writtenUnitLessons,232);assert.equal(Object.keys(course.unitLessons).length,232);
 for(const b of Object.keys(packs)){const c=course.coverage.byBani[b];assert.equal(c.firstLineNotes,Object.keys(course.closeTextNotes).filter(k=>k.startsWith(b+'|')).length);assert.equal(c.draftLessons,Object.keys(course.unitLessons).filter(k=>k.startsWith(b+'|')).length);if(b!=='jaap')assert.deepEqual(c,prior.coverage.byBani[b]);else assert.deepEqual([c.firstLineNotes,c.draftLessons],[406,105]);}
});
check('Anand 24 stays withheld and all Jaap 106 onward remain pending',()=>{
 const held=packs.anand.units.find(u=>u.id==='anand24');assert.equal(held.lines.length,6);assert.ok(held.lines.some(l=>l.held));assert.ok(!course.unitLessons['anand|anand24']);for(const l of held.lines)assert.ok(!course.closeTextNotes['anand|'+l.id]);
 for(const u of packs.jaap.units.slice(105)){assert.ok(!course.unitLessons['jaap|'+u.id]);for(const l of u.lines)assert.ok(!course.closeTextNotes['jaap|'+l.id]);}
});
check('Research is additive, authority remains unchanged and disputed alternatives remain exposed',()=>{
 for(const k of ['editorialStatus','reviewer','rightsStatus','publicationAllowed','sourceOriginalUnchanged','boundManifestSHA256','baseSourceCommit'])assert.deepEqual(course.meta[k],prior.meta[k]);assert.equal(course.coverage.reviewedUnitLessons,0);assert.equal(course.coverage.reviewedSourceMeaningLines,0);
 assert.deepEqual(course.meta.references.slice(0,prior.meta.references.length),prior.meta.references);assert.deepEqual(course.sourceChecks.slice(0,prior.sourceChecks.length),prior.sourceChecks);
 assert.equal(new Set(course.meta.references.map(r=>r.key)).size,course.meta.references.length);
 for(const [id,term] of [['jaap093.line02','unseen'],['jaap100.line04','place'],['jaap102.line02','primal'],['jaap104.line01','unbroken'],['jaap105.line03','drying']])assert.ok(course.closeTextNotes['jaap|'+id].interpretiveCaution.toLowerCase().includes(term));
});
class Element{constructor(tag){this.tagName=tag.toUpperCase();this.className='';this.dataset={};this.attributes={};this.children=[];this.value='';}set textContent(v){this.value=String(v);this.children=[];}get textContent(){return this.value+this.children.map(x=>typeof x==='string'?x:x.textContent).join('');}append(...v){this.children.push(...v);}replaceChildren(...v){this.value='';this.children=[...v];}setAttribute(k,v){this.attributes[k]=String(v);}getAttribute(k){return this.attributes[k]??null;}}
check('Actual learning renderer displays all added source-specific teaching and rejects wrong hashes',()=>{
 const window={};vm.runInNewContext(candidate('learning/learning-ui.js').toString(),{window,document:{createElement:t=>new Element(t)}});const ui=window.GLP_NitnemLearning;
 for(const u of units){assert.equal(ui.unitLesson(course,'jaap',u,'read','continuous'),null);const rendered=ui.unitLesson(course,'jaap',u,'study','passage');assert.ok(rendered.textContent.includes(course.unitLessons['jaap|'+u.id].study.closeReading));assert.ok(rendered.textContent.includes('HUMAN REVIEW PENDING'));for(const l of u.lines){const n=course.closeTextNotes['jaap|'+l.id],inline=ui.lineNote(course,'jaap',l),detail=ui.lineDetails(course,'jaap',l,u);assert.ok(inline.textContent.includes(n.simpleEn)&&inline.textContent.includes(n.simplePa));assert.ok(detail.textContent.includes(l.text)&&detail.textContent.includes(n.interpretiveCaution));assert.equal(ui.lineNote(course,'jaap',{...l,sha256:'0'.repeat(64)}),null);}}
 assert.match(ui.coverageText(course,'jaap'),/105 of 199 Study drafts.*406 of 782 line drafts/);
});
check('Appearance, header, saved-learning and embedded Japji bytes remain unchanged',()=>{
 for(const f of ['appearance.js','appearance.css','index.html','reader.css','japji.html','japji-assets/js/japji-full.js','japji-assets/js/shared-learning.js','learning/learning-ui.js','continuous-core.js'])assert.ok(candidate(f).equals(raw('nitnem/'+f)),f);
 assert.match(candidate('index.html').toString(),/id="pace"[^>]*max="200"/);
 for(const [p,h] of Object.entries(report.originalFilesPreserved))assert.equal(sha(raw(p)),h,p);
});
check('Candidate reader differs only by course hash/path; worker differs only by cache constants',()=>{
 const hash=sha(candidate('learning/course.v15.json'));let r=candidate('reader.js').toString().replace(hash,sha(raw('nitnem/learning/course.v14.json'))).replace("jsonBytes('learning/course.v15.json',EXPECTED_LEARNING)","jsonBytes('learning/course.v14.json',EXPECTED_LEARNING)");assert.equal(r,raw('nitnem/reader.js').toString());
 const strip=s=>s.replace(/^const (VERSION|PREFIX|EXPECTED)=.*;$/gm,'');assert.equal(strip(candidate('sw.js').toString()),strip(raw('nitnem/sw.js').toString()));
});
check('All 46 candidate assets and 45 cached assets match independently recomputed hashes',()=>{
 const sw=candidate('sw.js').toString(),m=JSON.parse(sw.match(/^const EXPECTED=(\{[^\n]+\});/m)[1]);assert.equal(Object.keys(m).length,45);assert.equal(Object.keys(report.assetHashes).length,46);assert.ok(sw.includes('glp-nitnem-learning-v15-review:'));
 for(const [rel,h] of Object.entries(m)){assert.ok(rel.startsWith('./')&&!rel.includes('..'));assert.equal(sha(candidate(rel.slice(2))),h,rel);}for(const [rel,h] of Object.entries(report.assetHashes))assert.equal(sha(candidate(rel)),h,rel);
 assert.equal(report.liveDeployment,false);assert.equal(report.humanReviewed,0);assert.equal(report.independentModelReview,false);
});
const failed=results.filter(r=>r.status==='FAIL').length;const result={status:failed?'FAIL':'PASS',checks:results.length,failed,sourceRecords:979,studyLessons:232,addedCoveredRecords:60,newMainExplanations:59,priorMainReuses:1,addedStudyLessons:15,liveDeployment:false,environment:'Node with the actual learning renderer and a DOM stub; not browser or scholarly review',results};
fs.writeFileSync(path.join(out,'evidence/contract.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));if(failed)process.exitCode=1;
